from collections import Counter, deque

def trans(grid):
    h,w=len(grid),len(grid[0]); bg=Counter(v for row in grid for v in row).most_common(1)[0][0]
    out=[[bg]*w for _ in range(h)]; seen=set()
    for r in range(h):
      for c in range(w):
        col=grid[r][c]
        if col==bg or (r,c) in seen: continue
        q=deque([(r,c)]); seen.add((r,c)); cells=[]
        while q:
          y,x=q.popleft(); cells.append((y,x))
          for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
            if 0<=yy<h and 0<=xx<w and (yy,xx) not in seen and grid[yy][xx]==col:
              seen.add((yy,xx));q.append((yy,xx))
        if len(cells)>=5:
          ys=[a for a,b in cells];xs=[b for a,b in cells]
          for y in range(min(ys),max(ys)+1):
            for x in range(min(xs),max(xs)+1):out[y][x]=col
    return out
